INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(20401, 'Ezekiel 40:39', 'Ezekiel', 40, 39, '&nbsp;د دروازې د ډيوډۍ سره په دواړه خواو کښې دوه مېزونه وُو، په کومو به چې د سوزولو د نذرانو، د ګناه د نذرانو او د ګناه د تاوان د نذرانو څاروى حلالولے شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20402, 'Ezekiel 40:40', 'Ezekiel', 40, 40, '&nbsp;د کوټې دروازې د کوټې د بهرنى دېوال سره، د پوړو سره نزدې د شمال دروازې ته د داخلېدو په لار هلته هم دوه مېزونه وُو، او د پوړو په بل طرف هم دوه مېزونه وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20403, 'Ezekiel 40:41', 'Ezekiel', 40, 41, '&nbsp;نو بيا د دروازې په يوې خوا کښې هم څلور مېزونه وُو او په بله خوا کښې هم څلور مېزونه وُو. دا ټول اتۀ مېزونه وُو په کومو به چې د قربانۍ څاروى حلالېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20404, 'Ezekiel 40:42', 'Ezekiel', 40, 42, '&nbsp;نو هلته هم څلور مېزونه د تراشلے شوو کاڼو نه د سوزېدونکې قربانۍ دپاره جوړ شوى وُو چې يو دېرش نيم اِنچه اوږدۀ او پلن وُو او يوويشت اِنچه لوړ وُو. په دې مېزونو باندې د قربانۍ د څاروو د حلالېدلو دپاره د قصابانو چړې او نور څيزونه پراتۀ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20405, 'Ezekiel 40:43', 'Ezekiel', 40, 43, '&nbsp;په ګېرچاپېره دېوال کښې د دوو خُلو والا کُنډې راځوړندې وې چې يو څپک اوږدې وې. دا مېزونه د نذرانو د څاروو دپاره وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20406, 'Ezekiel 40:44', 'Ezekiel', 40, 44, '&nbsp;نو بيا مونږ دننه دربار ته ننوتو، هلته د شمالى دروازې سره يوه کوټه وه چې دننه دربار طرف ته کولاو وه او د هغې مخ جنوب طرف ته وه. د جنوبى دروازې سره هم دا شان کوټه وه چې د هغې مخ شمال طرف ته وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20407, 'Ezekiel 40:45', 'Ezekiel', 40, 45, '&nbsp;هغه سړى ما ته ووئيل، د کومې کوټې چې د جنوب طرف ته يې مخه ده د هغه اِمامانو دپاره ده څوک چې د مالِک خُدائ په کور کښې مشران دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20408, 'Ezekiel 40:46', 'Ezekiel', 40, 46, '&nbsp;او هغه کوټه د کومې مخه چې شمال خوا ته ده د هغه اِمامانو دپاره ده څوک چې د قربان‌ګاه مشران دى. او هغوئ د صدوق زامن دى، څوک چې د ليويانو د قبيلې يواځې هغه کسان دى چا ته چې د مالِک خُدائ په حضور کښې د خِدمت کولو اجازت ورکړے شوے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20409, 'Ezekiel 40:47', 'Ezekiel', 40, 47, '&nbsp;نو بيا هغه سړى د مالِک خُدائ د کور دننه دربار ناپ کړو او هغه يو سل او پينځۀ اويا فټه اوږد او يو سل او پينځۀ اويا فټه پلن وو. او قربان‌ګاه د دربار په صحن کښې د مالِک خُدائ د کور مخې ته وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20410, 'Ezekiel 40:48', 'Ezekiel', 40, 48, '&nbsp;بيا هغۀ زۀ د مالِک خُدائ د کور دننه کوټې ته راوستلم. او هغۀ د ډيوډۍ د ستنو ناپ واخستو، او هغه پاو کم نهۀ فټه په هرې خوا پلنې وې، او په خپله د داخلېدو د دروازې پلنوالے څليريشت فټه وو، او يو بل دېوال وو په هره خوا کښې چې پاو کم شپږ فټه وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20411, 'Ezekiel 40:49', 'Ezekiel', 40, 49, '&nbsp;د داخلېدو د کوټې پلنوالے پينځۀ دېرش فټه وو، او اوږدوالے يې يوويشت فټه وو. او دې کوټې ته لس پوړۍ ورختلې وې، د دروازې په دواړو خواو دېوالونو کښې ستنې ولاړې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20412, 'Ezekiel 41:1', 'Ezekiel', 41, 1, '&nbsp;بيا هغه سړى زۀ د خُدائ د کور مقدس ځائ ته راوستلم او هغۀ د دروازو ستنې ناپ کړې، دواړو خواو ته د ستنو پلنوالے لس نيم فټه وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20413, 'Ezekiel 41:2', 'Ezekiel', 41, 2, '&nbsp;د داخلېدو لار اوولس نيم فټه پلنه وه، او د دواړو خوا دېوال ‎پاو کم نهۀ فټه اوږد وو. هغۀ بهرنے مقدس ځائ هم ناپ کړو، دا اويا فټه اوږد وو او پينځۀ دېرش فټه پلن وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20414, 'Ezekiel 41:3', 'Ezekiel', 41, 3, '&nbsp;بيا هغه دننه مقدس ځائ ته لاړو او د داخلېدو د لارې ستنې ‎يې ناپ کړې، او هره يوه درې نيم فټه پلنه وه. د داخلېدو لار لس نيم فټه پلنه وه، او د دواړو خواؤ دېوالونه ‎پاو باندې دولس فټه پلن وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20415, 'Ezekiel 41:4', 'Ezekiel', 41, 4, '&nbsp;او هغۀ د دننه مقدس ځائ اوږدوالے ناپ کړو، هغه پينځۀ دېرش فټه وو، او د دې پلنوالے پينځۀ دېرش فټه وو. هغۀ ما ته ووئيل، ”دا د ټولو نه زيات مقدس ځائ دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20416, 'Ezekiel 41:5', 'Ezekiel', 41, 5, '&nbsp;بيا هغۀ د خُدائ د کور دېوال ناپ کړو، هغه لس نيم فټه پلن وو. او د خُدائ د کور ګېرچاپېره هر طرف ته کوټه اووۀ فټه پلنه وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20417, 'Ezekiel 41:6', 'Ezekiel', 41, 6, '&nbsp;دا کوټې درې منزله وې، او په هر منزل کښې دېرش کوټې وې. د خُدائ د کور د دېوال ګېرچاپېره پايې وې د دې دپاره چې دا د دې کوټو دپاره ټيک وې. نو چې د دې کوټو تيرونه دېوال کښې دننه نۀ لګېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20418, 'Ezekiel 41:7', 'Ezekiel', 41, 7, '&nbsp;د خُدائ د کور ګېرچاپېره د دوېم چت کوټې د اول چت نه غټې وې او د درېم چت کوټې د دوېم چت نه غټې وې. کومه ډانچه چې د خُدائ د کور ګېرچاپېره جوړه شوې وه د لاندې نه بره حالت کښې جوړه وه، نو هغه کوټې کولاو وې چې بره وې. د لاندې نه تر دريم چت پورې پوړۍ ختلې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20419, 'Ezekiel 41:8', 'Ezekiel', 41, 8, '&nbsp;ما وليدل چې د خُدائ د کور نه ګېرچاپېره اوچته چونتره وه، چې د کوټو بنياد وو. د دې ناپ تول لس نيم فټه اوچت وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20420, 'Ezekiel 41:9', 'Ezekiel', 41, 9, '&nbsp;د هغه کوټو بهرنے دېوال پاو کم نهۀ فټه پلن وو. د کوټو په مينځ کښې هغه کولاو ځائ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20421, 'Ezekiel 41:10', 'Ezekiel', 41, 10, '&nbsp;او د خُدائ د کور نه ګېرچاپېره د اِمامانو کوټې پينځۀ دېرش فټه پلنې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20422, 'Ezekiel 41:11', 'Ezekiel', 41, 11, '&nbsp;د کولاو ځائ نه دې کوټو ته د ورننوتلو لارې ورغلې وې، يوه په شمال کښې او بله په جنوب کښې وه، او بنياد چې دا کولاو ځائ په خپلو کښې يو ځائ کوى پاو کم نهۀ فټه کولاو وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20423, 'Ezekiel 41:12', 'Ezekiel', 41, 12, '&nbsp;يو بل عمارت چې مخه يې د خُدائ د کور د دربار مغرب طرف ته وه هغه يو سل دوويشت نيم فټه کولاو او يو سل او اووۀ پنځوس نيم فټه اوږد وو، او د هغې دېوالونه پاو کم نهۀ فټه پلن وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20424, 'Ezekiel 41:13', 'Ezekiel', 41, 13, '&nbsp;بيا هغۀ د خُدائ د کور ناپ وکړو، دا يو سل او پينځۀ اويا فټه اوږد وو، او د خُدائ د کور دربار او هغه عمارت چې د دې دېوالونو سره وو هغه هم يو سل او پينځۀ اويا فټه اوږد وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20425, 'Ezekiel 41:14', 'Ezekiel', 41, 14, '&nbsp;مشرق طرف ته د مالِک خُدائ د مقدس کور دربار د خُدائ د کور مخې سره يو سل او پينځۀ اويا فټه پلن وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20426, 'Ezekiel 41:15', 'Ezekiel', 41, 15, '&nbsp;بيا هغۀ د هغه عمارت اوږدوالے د دېوالونو سره ناپ کړو چې د خُدائ د کور دربار ته مخامخ وو، چې دا يو سل او پينځۀ اويا فټه وو. د مالِک خُدائ د کور دننه حِصه د مالِک خُدائ د کور ډيوډۍ، مقدس ځائ او د ټولو نه زيات مقدس ځائ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20427, 'Ezekiel 41:16', 'Ezekiel', 41, 16, '&nbsp;او وړې کړکۍ او د دې دريواړو نه ګېرچاپېره هالونه د دې هر څۀ نه وروستو او د ډيوډۍ سره ټول په لرګى پټ وُو. فرش او دېوال، تر کړکيانو پورې او کړکۍ هم پټې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20428, 'Ezekiel 41:17', 'Ezekiel', 41, 17, '&nbsp;د دروازو دپاسه کومه لار چې د مالِک خُدائ د کور دننه مقدس ځائ ته ورغلې وه او د هغې په دننه او بهر دېوالونو باندې هم', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20429, 'Ezekiel 41:18', 'Ezekiel', 41, 18, '&nbsp;د وزرو والا د مخلوق او د کجورو د ونو تصويرونه جوړ شوى وُو. او د وزرو والا مخلوق او د کجورو ونې يو د بل پسې نقش شوى وُو، او د هر يو وزرو والا مخلوق دوه مخونه وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20430, 'Ezekiel 41:19', 'Ezekiel', 41, 19, '&nbsp;انسانى مخ يې د کجورې يوې ونې طرف ته وو او د زمرى مخ يې د کجورې د بلې ونې طرف ته وو. دا تصويرونه ګېرچاپېره د خُدائ په کور کښې نقش شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20431, 'Ezekiel 41:20', 'Ezekiel', 41, 20, '&nbsp;د فرش نه تر د ننوتلو دروازې پورې پاس، او د بهرنى مقدس ځائ په دېوال باندې د وزرو والا د مخلوق او د کجورو د ونو تصويرونه جوړ شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20432, 'Ezekiel 41:21', 'Ezekiel', 41, 21, '&nbsp;د بهرنى مقدس ځائ د دروازو چوکاټونه مربع وُو او د ډېر زيات مقدس ځائ مخې ته هم د دې په شان وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20433, 'Ezekiel 41:22', 'Ezekiel', 41, 22, '&nbsp;هلته د لرګى يوه قربان‌ګاه وه چې پاو باندې پينځۀ فټه اوچته او درې نيم فټه پلنه وه. د دې ګوټونه، د دې بېخ، او د دې اړخونه د لرګى نه جوړ شوى وُو. هغه سړى ما ته ووئيل، ”دا هغه مېز دے چې د مالِک خُدائ په وړاندې ولاړ دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20434, 'Ezekiel 41:23', 'Ezekiel', 41, 23, '&nbsp;بهرنى دواړو مقدس ځايونو او ډېر زيات مقدس ځائ دوه دروازې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20435, 'Ezekiel 41:24', 'Ezekiel', 41, 24, '&nbsp;هرې يوې دروازې دوه پلې لرلې او هرې يوې پلې ته دوه قبضې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20436, 'Ezekiel 41:25', 'Ezekiel', 41, 25, '&nbsp;او د بهرنى مقدس ځائ په دروازو د وزرو والا مخلوق تصوير او د کجورو د ونې تصويرونه نقش وُو لکه څنګه چې په دېوالونو باندې نقش شوى وُو، او هلته د لرګو يو دالان د وړې کوټې مخې ته جوړ شوے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20437, 'Ezekiel 41:26', 'Ezekiel', 41, 26, '&nbsp;د وړې کوټې په بهرنى دېوالونو باندې وړې کړکۍ وې چې په هره يوه باندې د کجورو ونې نقش شوې وې. د خُدائ د کور د وړو کوټو مخې کښې هم د لرګو دالانونه وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20438, 'Ezekiel 42:1', 'Ezekiel', 42, 1, '&nbsp;بيا هغه سړى زۀ د شمال خوا ته بهرنى دربار ته بوتلم او زۀ يې د مالِک خُدائ د کور مخامخ دربار کوټو ته او بهرنى دېوال ته مخامخ د شمال خوا ته راوستلم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20439, 'Ezekiel 42:2', 'Ezekiel', 42, 2, '&nbsp;هغه کور چې دروازه يې د شمال طرف ته وه هغه يو سل او پينځۀ اويا فټه اوږده وه او اووۀ اتيا نيم فټه پلنه وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20440, 'Ezekiel 42:3', 'Ezekiel', 42, 3, '&nbsp;دواړه په دې حِصه کښې پينځۀ دېرش فټه کښې د دنننى دربار نه او په مخامخ بله حِصه کښې د بهرنى دربار نه، په دريواړو منزلونو کښې کړکۍ يو بل ته مخامخ وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20441, 'Ezekiel 42:4', 'Ezekiel', 42, 4, '&nbsp;د دې کوټو په مخکښې يوه دننه لار وه اوولس نيم فټه پلنه او يو سل او پينځۀ اويا فټه اوږده وه. د دې دروازې په شمال کښې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20442, 'Ezekiel 42:5', 'Ezekiel', 42, 5, '&nbsp;نو بره کوټې تنګې وې، ځکه چې په دې کښې هالونو د لاندې او مينځنى منزلونو د کور د کوټو په نسبت ډېر ځائ نيولے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20443, 'Ezekiel 42:6', 'Ezekiel', 42, 6, '&nbsp;د درېم چت په کوټو کښې ستنې نۀ وې، لکه څنګه چې د دربار وې، نو دا نسبت د لاندې او مينځنى چتونو نه لږې شان وړې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20444, 'Ezekiel 42:7', 'Ezekiel', 42, 7, '&nbsp;هلته بهرنے دېوال د کوټو او د بهرنى دربار سره برابر وو، او دا د کوټو مخې ته اووۀ اتيا نيم فټه اوږد وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20445, 'Ezekiel 42:8', 'Ezekiel', 42, 8, '&nbsp;نو د کوټو قطار د بهرنى دربار په طرف اووۀ اتيا نيم فټه اوږد وو، او د مقدس ځائ سره نزدې قطار يو سل او پينځۀ اويا فټه اوږد وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20446, 'Ezekiel 42:9', 'Ezekiel', 42, 9, '&nbsp;لاندې کوټو ته د مشرق طرف نه د ننوتو لار وه کومه چې دې ته د بهرنى دربار نه ورننوځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20447, 'Ezekiel 42:10', 'Ezekiel', 42, 10, '&nbsp;د خُدائ د کور جنوب طرف ته يو بله آبادى وه چې د مالِک خُدائ د کور مغرب طرف ته وه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20448, 'Ezekiel 42:11', 'Ezekiel', 42, 11, '&nbsp;چې د دې مخې ته د تېرېدو لاره وه. دا لکه د شمال د کوټو په شان وې، دا هم هغه هومره اوږدې او پلنې وې، او هم يو شان لارې او ناپ يې وو. د شمال د تېرېدو د دروازو په شان د دې', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20449, 'Ezekiel 42:12', 'Ezekiel', 42, 12, '&nbsp;د کوټو دروازې جنوب طرف ته وې. هلته يوه دروازه وه چې دا د حِفاظتى دېوال سره يو شان د مشرق طرف ته غزېدلې وه، په کومه چې يو کس کوټو ته ننوځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20450, 'Ezekiel 42:13', 'Ezekiel', 42, 13, '&nbsp;بيا هغۀ ما ته ووئيل، ”شمال او جنوب ته کوټې چې د مالِک خُدائ د کور دربار ته يې مخې دى د اِمامانو کوټې دى، چرته چې هغه اِمامان څوک چې د مالِک خُدائ په وړاندې ودرېدل نو هغوئ دې مقدسې نذرانې وخورى. هلته به هغوئ ډيرې مقدسې نذرانې کېږدى، يعنې د غلې نذرانې، د ګناه نذرانې او د ګناه د تاوان نذرانې، ځکه چې هغه ځائ مقدس دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20451, 'Ezekiel 42:14', 'Ezekiel', 42, 14, '&nbsp;کله چې اِمامان د مالِک خُدائ په مقدس کور کښې داخل شى، بيا به هغوئ تر هغه وخته بهرنى دربار ته نۀ ځى ترڅو چې هغوئ هغه مقدسې جامې ونۀ باسى په کومو کښې چې هغوئ خِدمت کولو، ځکه چې دا مقدسې دى. هغوئ له پکار دى چې نورې کپړې واچوى د دې نه مخکښې چې هغوئ هغه ځايونو ته ورشى کوم چې د نورو خلقو دپاره دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20452, 'Ezekiel 42:15', 'Ezekiel', 42, 15, '&nbsp;کله چې هغۀ د مالِک خُدائ د کور دننه هر څۀ ناپ کړل، بيا هغۀ زۀ په مشرقى دروازې بهر راوويستلم او هغۀ ګېرچاپېره ټول هر څۀ ناپ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20453, 'Ezekiel 42:16', 'Ezekiel', 42, 16, '&nbsp;هغۀ د ناپ تول په چوکۍ مشرقى دېوال ناپ کړو، دا اتۀ سوه او پينځۀ اويا فټه اوږد وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20454, 'Ezekiel 42:17', 'Ezekiel', 42, 17, '&nbsp;بيا هغۀ شمال طرف ته دېوال ناپ کړو، دا د ناپ په چوکې اتۀ سوه او پينځۀ اويا فټه وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20455, 'Ezekiel 42:18', 'Ezekiel', 42, 18, '&nbsp;هغۀ جنوبى طرف دېوال ناپ کړو، هغه د ناپ په چوکې اتۀ سوه او پينځۀ اويا فټه وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20456, 'Ezekiel 42:19', 'Ezekiel', 42, 19, '&nbsp;بيا هغه مغرب طرف ته تاو شو او هغه دېوال يې ناپ کړو، او د ناپ په چوکې دا اتۀ سوه او پينځۀ اويا فټه وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20457, 'Ezekiel 42:20', 'Ezekiel', 42, 20, '&nbsp;بيا هغۀ هغه څلور واړه طرفونه ناپ کړل. او د دې نه ګېرچاپېره دېوال وو، چې اتۀ سوه او پينځۀ اويا فټه اوږد او اتۀ سوه او پينځۀ اويا فټه پلن وو، د دې مقصد دا وو چې عام ځائ د مقدس ځائ نه جدا کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20458, 'Ezekiel 43:1', 'Ezekiel', 43, 1, '&nbsp;بيا زۀ هغه سړى هغه دروازې ته راوستلم چې د مشرق طرف ته يې مخ وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20459, 'Ezekiel 43:2', 'Ezekiel', 43, 2, '&nbsp;او ناګهانه ما وليدل چې د بنى اِسرائيلو د خُدائ پاک جلال د مشرق خوا نه راروان وو. د هغۀ آواز لکه د ډېرو اوبو د غرار په شان وو، او زمکه د هغۀ د جلال په وجه روښانه وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20460, 'Ezekiel 43:3', 'Ezekiel', 43, 3, '&nbsp;کومه رويا چې ما وليدله د هغه رويا په شان وه کومه چې ما ليدلې وه کله چې هغه د ښار تباه کولو له راغلو او د هغه رويا په شان چې ما د کبار د سيند په غاړه وليدله، او زۀ پړمخې پرېوتلم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20461, 'Ezekiel 43:4', 'Ezekiel', 43, 4, '&nbsp;د مالِک خُدائ جلال د مالِک خُدائ په کور کښې د نمرخاتۀ دروازې نه ورننوتو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20462, 'Ezekiel 43:5', 'Ezekiel', 43, 5, '&nbsp;بيا زۀ روح اوچت کړم او دننه دربار ته يې راوستلم، او د مالِک خُدائ جلال د خُدائ کور ډک کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20463, 'Ezekiel 43:6', 'Ezekiel', 43, 6, '&nbsp;کله چې هغه سړے زما خوا کښې ولاړ وو، ما دا واورېدل چې څوک ما ته د خُدائ د کور دننه نه خبرې کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20464, 'Ezekiel 43:7', 'Ezekiel', 43, 7, '&nbsp;هغۀ وفرمائيل، ”اے بنى آدمه، دا زما تخت او د پښو د لګولو مقام دے. دا هغه مقام دے چې زۀ به په کښې د تل دپاره د بنى اِسرائيلو په مينځ کښې اوسېږم. هغوئ او د هغوئ بادشاهان به نور په بُت‌خانو کښې بُت پرستى او زما د مقدس نوم سپکاوے نۀ کوى. او نۀ به نور دوئ د خپلو مړو بادشاهانو د علاقائى زيارتونو عزت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20465, 'Ezekiel 43:8', 'Ezekiel', 43, 8, '&nbsp;کله چې هغوئ خپل درشل زما درشل سره خوا کښې او د خپلو دروازو بازو زما د دروازو د بازوګانو سره ولګول، زما او د هغوئ په مينځ کښې صرف ‎يو دېوال وو، هغوئ زما د مقدس نوم بې‌حرمتى په خپلو بدو عملونو سره وکړه. نو ما په خپله غصه کښې هغوئ تباه کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20466, 'Ezekiel 43:9', 'Ezekiel', 43, 9, '&nbsp;هغوئ دې اوس خپله بُت پرستى او د خپلو بادشاهانو زيارتونه زما د مخې نه اخوا کړى، او زۀ به د هغوئ په مينځ کښې د تل دپاره اوسېږم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20467, 'Ezekiel 43:10', 'Ezekiel', 43, 10, '&nbsp;اے بنى آدمه، د مالِک خُدائ کور د بنى اِسرائيل قوم ته وښايه، چې هغوئ په خپلو ګناهونو وشرميږى. پرېږده چې هغوئ په غور سره نقشه وګورى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20468, 'Ezekiel 43:11', 'Ezekiel', 43, 11, '&nbsp;او کۀ چرې هغوئ په خپلو ټولو کارونو باندې وشرميږى کوم چې هغوئ کړى دى، نو هغوئ ته د خُدائ د کور نقشه او د هغې ترتيب، د هغې د وتو لارې او د داخلېدو لارې، د هغې ټوله نقشه او د هغې اصُول او احکام وښايه. دا د هغوئ د وړاندې وليکه نو چې هغوئ د دې ترتيب وفادارى وکړى او د دې د احکامو پيروى وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20469, 'Ezekiel 43:12', 'Ezekiel', 43, 12, '&nbsp;د مالِک خُدائ د کور دا قانون دے، د غرۀ دپاسه ګېرچاپېره علاقه به د ټولو نه زياته مقدسه وى. دا د خُدائ د کور قانون دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20470, 'Ezekiel 43:13', 'Ezekiel', 43, 13, '&nbsp;”دا د قربان‌ګاه په اوږدو ناپ تول دے، د قربان‌ګاه نه ګېرچاپېره غاړه يوويشت اِنچه ژوره وه او يوويشت اِنچه پلنه وه، او د هغې ګېرچاپېره غاړه نهۀ اِنچه پلنه وه. او هم دا د قربان‌ګاه اوچتوالے دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20471, 'Ezekiel 43:14', 'Ezekiel', 43, 14, '&nbsp;په زمکه د غاړې نه بره تر ښکته چجې پورې دا درې نيم فټه اوچته وه او يوويشت اِنچه پلنه وه. او د وړې چجې نه تر غټې چجې پورې دا اووۀ فټه اوچته او يوويشت اِنچه پلنه وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20472, 'Ezekiel 43:15', 'Ezekiel', 43, 15, '&nbsp;د قربان‌ګاه برنۍ برخه اووۀ فټه اوچته وه چې قربانى به په کښې سوزولے کېدله او د هغې په هر يو ګوټ کښې يو يو ښکر لګولے شوے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20473, 'Ezekiel 43:16', 'Ezekiel', 43, 16, '&nbsp;قربان‌ګاه د سر څلور ګوټونه وُو، يوويشت فټه اوږدۀ او يوويشت فټه پلن وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20474, 'Ezekiel 43:17', 'Ezekiel', 43, 17, '&nbsp;بره چجه هم مربع وه، څليريشت نيم فټه اوږده او څليريشت نيم فټه پلنه وه، چې غاړه يې يوويشت اِنچه وه او ګېرچاپېره لس نيم اِنچه غاړه وه. او د قربان‌ګاه پوړۍ نمرخاتۀ طرف ته وې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20475, 'Ezekiel 43:18', 'Ezekiel', 43, 18, '&nbsp;بيا هغۀ ما ته وفرمائيل، ”اے بنى آدمه، مالِک قادر مطلق خُدائ داسې فرمائى چې، د سوزېدونکې قربانۍ د نذرانو دپاره به دا اصُول وى او په قربان‌ګاه به وينه وشيندلے شى کله چې دا تياره شى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20476, 'Ezekiel 43:19', 'Ezekiel', 43, 19, '&nbsp;تاسو به يو ځوان سخے د ګناه د نذرانې دپاره اِمامانو له ورکړئ، څوک چې ليويان دى او د صدوق د نسل نه دى، او څوک چې زما وړاندې خِدمت کوى، مالِک خُدائ دا فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20477, 'Ezekiel 43:20', 'Ezekiel', 43, 20, '&nbsp;تاسو د دې نه لږه وينه واخلئ او د قربان‌ګاه په څلورو ګوټونو کښې په ښکرونو باندې په بره حِصه کښې او د هغې په غاړو باندې وشيندئ، او دغه شان قربان‌ګاه مقدسه کړئ او د هغې دپاره کفاره ورکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20478, 'Ezekiel 43:21', 'Ezekiel', 43, 21, '&nbsp;تاسو به يو غوَيے د ګناه د نذرانې دپاره واخلئ او د خُدائ د کور په مقرر شوى ځائ د مقدس ځائ نه بهر به يې وسوزوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20479, 'Ezekiel 43:22', 'Ezekiel', 43, 22, '&nbsp;په دوېمه ورځ به تاسو بې‌عېبه چېلے د ګناه د نذرانې دپاره پېش کړئ، او قربان‌ګاه به پرې داسې مقدسه کړئ لکه څنګه چې مو په غوَيى باندې پاکه کړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20480, 'Ezekiel 43:23', 'Ezekiel', 43, 23, '&nbsp;کله چې تاسو د دې د پاکولو کار ختم کړئ، نو تاسو به بيا يو ځوان سخے او ګډورے د رمې نه نذرانه کړئ، چې دواړه بې‌عېبه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20481, 'Ezekiel 43:24', 'Ezekiel', 43, 24, '&nbsp;تاسو دا د مالِک خُدائ په وړاندې پېش کړئ، او اِمامان به په دوئ مالګه واچوى او دا به د سوزېدونکې قربانۍ په طور پېش کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20482, 'Ezekiel 43:25', 'Ezekiel', 43, 25, '&nbsp;تاسو به د اووۀ ورځو دپاره هره ورځ يو چېلے د ګناه د نذرانې دپاره پېش کوئ، تاسو به د رمې نه يو ځوان غوَيے او يو ګډورے هم پېش کوئ، چې درې واړه بې‌عېبه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20483, 'Ezekiel 43:26', 'Ezekiel', 43, 26, '&nbsp;د اووۀ ورځو دپاره دې هغوئ د قربان‌ګاه او د هغې د پاکولو دپاره فديه پېش کړى، نو داسې به هغوئ دا وقف کړى‎.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20484, 'Ezekiel 43:27', 'Ezekiel', 43, 27, '&nbsp;د دې ورځو په آخر کښې، د اتمې ورځې نه وروستو هم اِمامان به په قربان‌ګاه ستاسو سوزېدونکې او د عبادت نذرانې پېش کړى. بيا به زۀ تاسو قبول کړم. مالِک قادر مطلق خُدائ دا فرمائى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20485, 'Ezekiel 44:1', 'Ezekiel', 44, 1, '&nbsp;بيا زۀ‎ هغه سړى واپس د مقدس ځائ بهرنۍ دروازې ته راوستلم، کومه چې د نمرخاتۀ طرف ته وه، او دا بنده وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20486, 'Ezekiel 44:2', 'Ezekiel', 44, 2, '&nbsp;مالِک خُدائ ما ته وفرمائيل، ”دا دروازه به بنده وى. دا به کله هم نۀ کولاويږى. هيڅوک به په دې نۀ ورننوځى. دا به بنده وى ځکه چې مالِک خُدائ، د بنى اِسرائيلو خُدائ پاک، په دې دروازه دننه شوے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20487, 'Ezekiel 44:3', 'Ezekiel', 44, 3, '&nbsp;صرف شهزاده په دې کښې دننه کښېناستے شى چې د مالِک خُدائ په حضور کښې خوراک وکړى. هغه دې د برنډې د لارې نه دننه راشى او په هم هغه لار دې بهر لاړ شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20488, 'Ezekiel 44:4', 'Ezekiel', 44, 4, '&nbsp;بيا زۀ هغه سړى د خُدائ د کور مخامخ د شمالى دروازې په لار راوستلم. ما وکتل او د مالِک خُدائ جلال مې وليدلو چې د مالِک خُدائ کور ډکوى، او زۀ پړمخې پرېوتلم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20489, 'Ezekiel 44:5', 'Ezekiel', 44, 5, '&nbsp;مالِک خُدائ ما ته وفرمائيل چې، ”اے بنى آدمه، په غور سره وګوره، او په غور سره واؤره، او هر هغه څۀ ته خيال وکړه چې درته زۀ د مالِک خُدائ د کور د ټولو احکامو په حقله فرمايم. د مالِک خُدائ مقدس کور ته د تلو راتلو طريقو ته خيال وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20490, 'Ezekiel 44:6', 'Ezekiel', 44, 6, '&nbsp;د بنى اِسرائيلو سرکشه قوم ته ووايه، مالِک قادر مطلق خُدائ داسې فرمائى، اے د بنى اِسرائيل قومه، ستاسو دا دومره حرام کارونه بس دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20491, 'Ezekiel 44:7', 'Ezekiel', 44, 7, '&nbsp;ستاسو د ټولو حرامو کارونو سره، تاسو په ظاهر او باطن ناسنته غېر مُلکيان زما مقدس ځائ ته راوستل، تاسو زما د کور بې‌حرمتى وکړه کله چې تاسو ما ته خوراک، وازګه او وينه پېش کړه، او تاسو زما لوظ مات کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20492, 'Ezekiel 44:8', 'Ezekiel', 44, 8, '&nbsp;د دې په ځائ چې تاسو زما د مقدس څيزونو خِدمت په خپله وکړئ، تاسو نورو خلقو ته زما د مقدس ځائ اختيار ورکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20493, 'Ezekiel 44:9', 'Ezekiel', 44, 9, '&nbsp;مالِک قادر مطلق خُدائ داسې فرمائى چې، يو غېر مُلکى به هم چې په ظاهر او باطن ناسنته وى هغه به زما مقدس ځائ کښې داخل نۀ شى، او نۀ به هغه غېر مُلکيان چې د بنى اِسرائيلو په مينځ کښې اوسيږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20494, 'Ezekiel 44:10', 'Ezekiel', 44, 10, '&nbsp;”هغه ليويان چا چې زما نه جدائى اختيار کړه کله چې د بنى اِسرائيلو قوم بې‌لارې شو او هغوئ چا چې زما په ځائ د خپلو بُتانو پيروى وکړه به د خپلې ګناه سزا وزغمى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20495, 'Ezekiel 44:11', 'Ezekiel', 44, 11, '&nbsp;هغوئ دې زما په مقدس کور کښې خِدمت وکړى، د خُدائ د کور د دروازو ذمه وارى دې واخلى او په دې کښې دې خِدمت کوى، هغوئ دې سوزېدونکې نذرانې او قربانۍ د خلقو دپاره حلالې کړى او د خلقو په وړاندې دې ودريږى او د هغوئ خِدمت دې وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20496, 'Ezekiel 44:12', 'Ezekiel', 44, 12, '&nbsp;خو ځکه دوئ د بُتانو عبادت د خلقو دپاره وکړو او د بنى اِسرائيلو قوم يې په ګناه کښې اخته کړو، نو په دې وجه ما قسم وخوړلو چې هغوئ به ضرور د خپلو ګناهونو سزا وزغمى، مالِک قادر مطلق خُدائ دا فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20497, 'Ezekiel 44:13', 'Ezekiel', 44, 13, '&nbsp;هغوئ به نور د اِمامانو په توګه زما د خِدمت دپاره نزدې نۀ راځى او نۀ به زما مقدسو څيزونو له نزدې راځى او نۀ به زما ډېرو مقدسو نذرانو ته نزدې کيږى، هغوئ به ضرور د خپلو حرامو کارونو شرم وزغمى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20498, 'Ezekiel 44:14', 'Ezekiel', 44, 14, '&nbsp;خو بيا هم به زۀ هغوئ ته د خُدائ د کور خِدمت او د هغه ټول کار ذمه وارى ورکړم چې په دې کښې کول په کار دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20499, 'Ezekiel 44:15', 'Ezekiel', 44, 15, '&nbsp;”خو هغه اِمامان، څوک چې ليويان دى او د صدوق د نسل نه دى او چا چې په وفادارۍ سره زما د مقدس کور خِدمت وکړو کله چې بنى اِسرائيل زما نه بې‌لارې شول، هغوئ به نزدې راشى زما د وړاندې به خِدمت وکړى، هغوئ به د وازګو او وينې قربانۍ پېش کولو دپاره زما په وړاندې ودريږى، مالِک خُدائ دا فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20500, 'Ezekiel 44:16', 'Ezekiel', 44, 16, '&nbsp;صرف هغوئ به زما مقدس مقام ته رادننه شى، يواځې هغوئ به زما مېز ته نزدې راشى او زما په حضور کښې به خِدمت کوى او زما د فرائضو ذمه وارى به سمبالوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');